<section><h2>Cereri de retragere</h2><p>Verifică termenul legal, identifică abonamentul și procesează separat încetarea și eventualele sume datorate în Stripe. Înregistrarea unei cereri nu operează automat o anulare sau o rambursare.</p>
<?php foreach($legalRequests as $request): $d=Zion\EncryptedPayload::decode($request['payload']); ?><article><h3><?= e($d['name']) ?> · <?= e($formatDate($request['created_at'])) ?></h3><p><?= e($d['email']) ?><br><?= e($d['contract']) ?><br><?= e($request['status']) ?></p><details><summary>Confirmarea cererii</summary><pre><?= e($d['receipt']) ?></pre></details>
<?php if($request['status']==='new'): ?><form method="post"><input type="hidden" name="_csrf" value="<?= e(Zion\Security::csrf()) ?>"><input type="hidden" name="action" value="withdrawal_resolve"><input type="hidden" name="request_id" value="<?= e($request['id']) ?>"><label>Notă internă privind soluționarea<textarea name="notes" required minlength="3" maxlength="1000"></textarea></label><button>Marchează soluționată</button></form><?php else: ?><p><?= e($request['notes']) ?></p><?php endif ?></article><?php endforeach ?><?php if(!$legalRequests): ?><p>Nicio cerere înregistrată.</p><?php endif ?></section>
